import hashlib
import hmac
import os
import time
import json
import unicodedata
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import parse_qs, urlparse
import threading
import re

SECRET_KEY = os.environ.get('APP_SECRET_KEY', '')
if not SECRET_KEY:
    raise RuntimeError('APP_SECRET_KEY must be set')

# Secure password storage with constant-time comparison
class UserStore:
    def __init__(self):
        self._lock = threading.Lock()
        self._users = {}
        self._failed_attempts = {}
        self._lockout_duration = 300
        self._max_attempts = 5

    def register_user(self, username, password, role='user'):
        """Register user with normalized username to prevent duplicates."""
        normalized = self._normalize_username(username)
        with self._lock:
            if normalized in self._users:
                return False
            salt = os.urandom(32)
            pwd_hash = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 310000)
            self._users[normalized] = {
                'salt': salt,
                'hash': pwd_hash,
                'role': role,
                'created': time.time(),
                'display_name': normalized  # Store normalized form only
            }
            return True

    def authenticate(self, username, password):
        """Authenticate user with rate limiting and constant-time comparison."""
        normalized = self._normalize_username(username)
        with self._lock:
            if self._is_locked_out(normalized):
                return None
            user = self._users.get(normalized)
            if user is None:
                # Perform dummy hash to prevent timing oracle
                dummy_salt = os.urandom(32)
                hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), dummy_salt, 310000)
                self._record_failure(normalized)
                return None
            pwd_hash = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), user['salt'], 310000)
            if hmac.compare_digest(pwd_hash, user['hash']):
                self._clear_failures(normalized)
                return {'username': normalized, 'role': user['role']}
            else:
                self._record_failure(normalized)
                return None

    def _normalize_username(self, username):
        """Normalize username: NFKC normalization, case fold, strip whitespace.
        This prevents homoglyph and case-based duplicate accounts."""
        # Step 1: Unicode NFKC normalization (maps compatibility chars)
        normalized = unicodedata.normalize('NFKC', username)
        # Step 2: Case folding for case-insensitive comparison
        normalized = normalized.casefold()
        # Step 3: Strip leading/trailing whitespace
        normalized = normalized.strip()
        # Step 4: Collapse internal whitespace
        normalized = re.sub(r'\s+', ' ', normalized)
        return normalized

    def _is_locked_out(self, username):
        record = self._failed_attempts.get(username)
        if record is None:
            return False
        if record['count'] >= self._max_attempts:
            if time.time() - record['last'] < self._lockout_duration:
                return True
            self._clear_failures(username)
        return False

    def _record_failure(self, username):
        if username not in self._failed_attempts:
            self._failed_attempts[username] = {'count': 0, 'last': 0}
        self._failed_attempts[username]['count'] += 1
        self._failed_attempts[username]['last'] = time.time()

    def _clear_failures(self, username):
        self._failed_attempts.pop(username, None)

    def get_user_by_normalized(self, normalized_username):
        """Look up user by already-normalized username."""
        with self._lock:
            return self._users.get(normalized_username)


class TokenManager:
    def __init__(self, secret):
        self._secret = secret.encode('utf-8') if isinstance(secret, str) else secret
        self._revoked = set()
        self._lock = threading.Lock()

    def create_token(self, user_info, ttl=3600):
        payload = json.dumps({
            'sub': user_info['username'],
            'role': user_info['role'],
            'exp': int(time.time()) + ttl,
            'jti': os.urandom(16).hex()
        }, separators=(',', ':'))
        sig = hmac.new(self._secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
        return f"{payload}|{sig}"

    def verify_token(self, token):
        try:
            parts = token.rsplit('|', 1)
            if len(parts) != 2:
                return None
            payload_str, sig = parts
            expected_sig = hmac.new(self._secret, payload_str.encode('utf-8'), hashlib.sha256).hexdigest()
            if not hmac.compare_digest(sig, expected_sig):
                return None
            payload = json.loads(payload_str)
            if payload.get('exp', 0) < time.time():
                return None
            with self._lock:
                if payload.get('jti') in self._revoked:
                    return None
            return payload
        except Exception:
            return None

    def revoke_token(self, jti):
        with self._lock:
            self._revoked.add(jti)


class AdminPanel:
    def __init__(self, user_store, token_manager):
        self._user_store = user_store
        self._token_manager = token_manager

    def change_user_role(self, admin_token, target_username, new_role):
        """Admin operation to change a user's role."""
        admin = self._token_manager.verify_token(admin_token)
        if admin is None or admin.get('role') != 'admin':
            return {'error': 'unauthorized', 'status': 403}

        valid_roles = {'user', 'moderator', 'admin'}
        if new_role not in valid_roles:
            return {'error': 'invalid role', 'status': 400}

        # Normalize the target username before lookup
        normalized_target = self._user_store._normalize_username(target_username)
        user = self._user_store.get_user_by_normalized(normalized_target)
        if user is None:
            return {'error': 'user not found', 'status': 404}

        with self._user_store._lock:
            user['role'] = new_role
        return {'success': True, 'status': 200}

    def list_users(self, admin_token):
        admin = self._token_manager.verify_token(admin_token)
        if admin is None or admin.get('role') != 'admin':
            return {'error': 'unauthorized', 'status': 403}
        with self._user_store._lock:
            return {
                'users': [
                    {'username': k, 'role': v['role'], 'display': v['display_name']}
                    for k, v in self._user_store._users.items()
                ],
                'status': 200
            }


def create_app():
    store = UserStore()
    tokens = TokenManager(SECRET_KEY)
    admin_panel = AdminPanel(store, tokens)

    # Bootstrap admin account
    store.register_user('admin', os.environ.get('ADMIN_PASSWORD', os.urandom(32).hex()), role='admin')

    return store, tokens, admin_panel


user_store, token_mgr, admin = create_app()


class RequestHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        path = urlparse(self.path).path
        content_length = int(self.headers.get('Content-Length', 0))
        if content_length > 65536:
            self._respond(413, {'error': 'too large'})
            return
        body = self.rfile.read(content_length)

        try:
            data = json.loads(body) if body else {}
        except json.JSONDecodeError:
            self._respond(400, {'error': 'invalid json'})
            return

        if path == '/auth/register':
            self._handle_register(data)
        elif path == '/auth/login':
            self._handle_login(data)
        elif path == '/admin/change-role':
            self._handle_change_role(data)
        else:
            self._respond(404, {'error': 'not found'})

    def _handle_register(self, data):
        username = data.get('username', '')
        password = data.get('password', '')
        if not username or not password:
            self._respond(400, {'error': 'missing fields'})
            return
        if len(username) > 64 or len(password) > 128:
            self._respond(400, {'error': 'field too long'})
            return
        if user_store.register_user(username, password):
            self._respond(201, {'success': True})
        else:
            self._respond(409, {'error': 'username taken'})

    def _handle_login(self, data):
        username = data.get('username', '')
        password = data.get('password', '')
        if not username or not password:
            self._respond(400, {'error': 'missing fields'})
            return
        result = user_store.authenticate(username, password)
        if result:
            token = token_mgr.create_token(result)
            self._respond(200, {'token': token})
        else:
            self._respond(401, {'error': 'invalid credentials'})

    def _handle_change_role(self, data):
        auth_header = self.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            self._respond(401, {'error': 'missing token'})
            return
        token = auth_header[7:]
        target = data.get('target_username', '')
        new_role = data.get('role', '')
        if not target or not new_role:
            self._respond(400, {'error': 'missing fields'})
            return
        result = admin.change_user_role(token, target, new_role)
        self._respond(result.get('status', 500), result)

    def _respond(self, status, body):
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(body).encode('utf-8'))


if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), RequestHandler)
    server.serve_forever()
